using FastEndpoints;using MediatR;using F=OrderFlow.Payments.Application.Payments.PaymentFeatures;namespace OrderFlow.Payments.Api.Endpoints;public static class PaymentEndpoints
{public class IdReq{public Guid Id{get;set;}}public sealed class CreateReq{public Guid OrderId{get;set;}public decimal Amount{get;set;}public string Method{get;set;}="Card";}public sealed class MarkReq:IdReq{public string Reference{get;set;}=string.Empty;public string Reason{get;set;}=string.Empty;}public sealed class RefundReq:IdReq{public decimal Amount{get;set;}public string Reason{get;set;}=string.Empty;}
public sealed class Create(ISender s):Endpoint<CreateReq,F.Dto>{public override void Configure(){Post("/api/payments");AllowAnonymous();}public override async Task HandleAsync(CreateReq r,CancellationToken ct)=>await Send.ResponseAsync(await s.Send(new F.Create(r.OrderId,r.Amount,r.Method),ct),201,ct);}public sealed class Process(ISender s):Endpoint<IdReq,F.Dto>{public override void Configure(){Post("/api/payments/{id}/process");AllowAnonymous();}public override async Task HandleAsync(IdReq r,CancellationToken ct)=>await Send.OkAsync(await s.Send(new F.Process(r.Id),ct),ct);}public sealed class Get(ISender s):Endpoint<IdReq,F.Dto>{public override void Configure(){Get("/api/payments/{id}");AllowAnonymous();}public override async Task HandleAsync(IdReq r,CancellationToken ct)=>await Send.OkAsync(await s.Send(new F.GetById(r.Id),ct),ct);}public sealed class ByOrder(ISender s):Endpoint<IdReq,F.Dto>{public override void Configure(){Get("/api/orders/{id}/payment");AllowAnonymous();}public override async Task HandleAsync(IdReq r,CancellationToken ct)=>await Send.OkAsync(await s.Send(new F.GetByOrder(r.Id),ct),ct);}public sealed class Succeed(ISender s):Endpoint<MarkReq>{public override void Configure(){Post("/api/payments/{id}/succeed");AllowAnonymous();}public override async Task HandleAsync(MarkReq r,CancellationToken ct){await s.Send(new F.MarkSucceeded(r.Id,r.Reference),ct);await Send.NoContentAsync(ct);}}public sealed class Fail(ISender s):Endpoint<MarkReq>{public override void Configure(){Post("/api/payments/{id}/fail");AllowAnonymous();}public override async Task HandleAsync(MarkReq r,CancellationToken ct){await s.Send(new F.MarkFailed(r.Id,r.Reason),ct);await Send.NoContentAsync(ct);}}public sealed class Refund(ISender s):Endpoint<RefundReq,F.Dto>{public override void Configure(){Post("/api/payments/{id}/refunds");AllowAnonymous();}public override async Task HandleAsync(RefundReq r,CancellationToken ct)=>await Send.OkAsync(await s.Send(new F.RefundPayment(r.Id,r.Amount,r.Reason),ct),ct);}}

